    background-color: rgba(41, 41, 41, .6);
    color: #fff;
    border-radius: 5px;
    white-space: nowrap;
    font-weight: 400;
    font-size: 1.1rem
}

body .products-grid .product-item .product-item-info {
    height: 100%
}

body .products-grid .product-item .product-item-info .actions-primary .stock.unavailable {
    display: flex !important;
    align-items: center;
    justify-content: center;
    height: 40px;
    position: relative;
    bottom: -2px
}

.amshopby-slider-container .ui-slider-range {
    background: #333 !important
}

.amshopby-slider-container .am-slider .ui-slider-handle {
    border-radius: 2px !important;
