}

.page-products .columns {
    position: relative;
    z-index: 1
}

.toolbar-amount {
    display: block;
    line-height: 26px;
    margin: 0;
    padding: 8px 0 0;
    vertical-align: middle
}

.products.wrapper~.toolbar .toolbar-amount {
    display: none
}

.products.wrapper~.toolbar .field.limiter {
    display: none !important
}

.products.wrapper~.toolbar .pages {
    display: grid;
    width: 100%
}

.products.wrapper~.toolbar .pages .items {
    display: flex;
    align-items: center;
    justify-content: center
}

.products.wrapper~.toolbar .pages .items .item {
    margin: 0
}

.products.wrapper~.toolbar .pages .items .item .page {
    padding: 5px 15px;
    margin: 0 5px;
    background: 0 0;
    color: #000;
    line-height: 36px;
    font-size: 14px;
    height: 50px;
    display: flex;
    align-items: center;
    text-align: center;
    text-decoration: none;
    border: 1px solid #f0f0f0;
    border-radius: 2px;
    background-color: #fff;
    transition-property: background-color, color, border-color;
    transition-duration: .2s;
    transition-timing-function: linear
}

.products.wrapper~.toolbar .pages .items .item .page:hover {
    border-color: #a91e23;
    color: #fff;
    background-color: #a91e23
}

.products.wrapper~.toolbar .pages .items .item .action {
    padding: 5px 15px;
    color: #000;
    line-height: 36px;
    font-size: 14px;
    height: 50px;
    display: flex;
    align-items: center;
    text-align: center;
    text-decoration: none;
    border: 1px solid #e6e6e6;
    border-radius: 2px;
    background-color: #fff;
    transition-property: background-color, color, border-color;
    transition-duration: .2s;
    transition-timing-function: linear;
    width: auto;
    justify-content: center
}

.products.wrapper~.toolbar .pages .items .item .action.next {
    padding-left: 20px !important
}

.products.wrapper~.toolbar .pages .items .item .action.next:before {
    display: none
}

.products.wrapper~.toolbar .pages .items .item .action.next:after {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-size: 32px;
    line-height: inherit;
    color: #000;
    content: '\e608';
    font-family: 'icons-blank-theme';
    margin: 0;
    vertical-align: top;
    display: inline-block;
    font-weight: 400;
    overflow: hidden;
    speak: none;
    text-align: center
}

.products.wrapper~.toolbar .pages .items .item .action.next span {
    border: 0;
    clip: rect(0, 0, 0, 0);
    height: auto;
    margin: 0;
    overflow: hidden;
    padding: 0;
    position: static;
    width: auto
}

.products.wrapper~.toolbar .pages .items .item .action.next span:before {
    display: none
}

.products.wrapper~.toolbar .pages .items .item .action.next span.label {
    display: none
}

.products.wrapper~.toolbar .pages .items .item .action.previous {
    padding-right: 20px !important
}

.products.wrapper~.toolbar .pages .items .item .action.previous:before {
    font-size: 32px;
    line-height: inherit;
    color: #000
}

.products.wrapper~.toolbar .pages .items .item .action.previous span {
    border: 0;
    clip: rect(0, 0, 0, 0);
    height: auto;
    margin: 0;
    overflow: hidden;
    padding: 0;
    position: static;
    width: auto
}

.products.wrapper~.toolbar .pages .items .item .action.previous span:before {
    display: none
}

.products.wrapper~.toolbar .pages .items .item .action.previous span.label {
    display: none
}

.products.wrapper~.toolbar .pages .items .item.current .page {
    border-color: #a91e23;
    color: #fff;
    background-color: #a91e23
}

.toolbar-products {
    margin-bottom: 40px;
    text-align: center
}

.toolbar-products .pages {
    display: none
}

.products.wrapper~.toolbar-products .pages {
    display: block
}

.toolbar-products .limiter .control {
    display: inline-block
}

.sorter {
    padding: 4px 0 0
}

.products.wrapper~.toolbar .sorter {
    display: none
}

.sorter .sorter-action {
    position: relative;
    top: -2px
}

.sorter-options {
    margin: 0 0 0 7px;
    width: auto
}

.sorter-action {
    vertical-align: top;
    display: inline-block;
    text-decoration: none
}

.sorter-action>span {
    border: 0;
    clip: rect(0, 0, 0, 0);
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    position: absolute;
    width: 1px
}

.sorter-action:before {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-size: 28px;
    line-height: 32px;
    color: #8f8f8f;
    content: '\e613';
    font-family: 'icons-blank-theme';
    vertical-align: middle;
    display: inline-block;
    font-weight: 400;
    overflow: hidden;
    speak: none;
    text-align: center
}

.sorter-action:hover:before {
    color: #333
}

.sorter .sort-desc:before {
    content: '\e614'
}

.modes {
    display: none
}

.limiter-options {
    margin: 0 5px 0 7px;
    width: auto
}

.limiter-label {
    font-weight: 400
}

.page-products .toolbar .limiter {
    display: none
}

:root {
