.accordion a {
    position: relative;
    display: -webkit-box;
    display: -webkit-flex;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-orient: vertical;
    -webkit-box-direction: normal;
    -webkit-flex-direction: column;
    -ms-flex-direction: column;
    flex-direction: column;
    width: 100%;
    padding: 1.5rem 3rem 2rem 1rem;
    color: #7288a2;
    font-size: 1.9rem;
    font-weight: 400;
    border-bottom: 1px solid #e5e5e5
}

.accordion a:hover,
.accordion a:hover:after {
    cursor: pointer;
    color: #03b5d2
}

.accordion a:hover:after {
    border: 1px solid #03b5d2
}

.accordion a.active {
    color: #03b5d2;
    border-bottom: 1px solid #03b5d2
}

.accordion a:after {
    font-family: 'Ionicons';
    content: '\f218';
    position: absolute;
    float: right;
    right: 1rem;
    font-size: 2rem;
    color: #7288a2;
    padding: 2px;
    padding-top: 4px;
    width: 30px;
    height: 30px;
    -webkit-border-radius: 50%;
    -moz-border-radius: 50%;
    border-radius: 50%;
    border: 1px solid #7288a2;
    text-align: center
}

.accordion a.active:after {
    font-family: 'Ionicons';
    content: '\f209';
    color: #03b5d2;
    border: 1px solid #03b5d2
}

.accordion .content {
    opacity: 0;
    padding: 0 1rem;
    max-height: 0;
    border-bottom: 1px solid #e5e5e5;
    overflow: hidden;
    clear: both;
    -webkit-transition: all .2s ease .15s;
    -o-transition: all .2s ease .15s;
    transition: all .2s ease .15s
}

.accordion .content.active {
    opacity: 1;
    padding: 1rem;
    max-height: 100%;
    -webkit-transition: all .35s ease .15s;
    -o-transition: all .35s ease .15s;
    transition: all .35s ease .15s
