    }
    .blog-search .block-content .blog-tags li {
        padding: 5px 15px;
        font-size: 12px
    }
    .post-item-date {
        font-size: 8px
    }
    .item .blog-content a {
        font-size: 14px
    }
    .item .readmore-btn {
        font-size: 13px
    }
    .blog-page .slick-next {
        right: 0
    }
    .blog-page .slick-prev {
        left: 0
    }
    .blog-categories {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        grid-gap: 10px
    }
    .blog-categories li a {
        font-size: 14px !important;
        padding: 1rem !important
    }
    .blog-search .block-content .blog-tags {
        gap: 10px;
        margin-top: 15px
    }
    .blog-page .block {
        margin-bottom: 0 !important
    }
    .blog-page .block-inner .slick-slide>div {
        margin-right: 10px
    }
    .blog-page .block-inner {
        margin-top: 10px !important;
        margin-bottom: 10px !important
    }
    .blog-page .block .title strong {
        margin-top: 10px !important;
        margin-bottom: 10px !important
    }
    .item .blog-content .post-item-link {
        height: 34px;
        overflow: hidden;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
