    }
    .blog-page .block-inner .slick-slider {
        margin-bottom: 0
    }
    .block-categories .slick-slide>div {
        margin-right: 10px
    }
}

@media only screen and (min-width:768px) and (max-width:960px) {
    .blog-categories {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        grid-gap: 20px
    }
}